class Solution:
    def hasTriple(self, weights: List[int], target: int) -> bool:
        n = len(weights)
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    if weights[i] + weights[j] + weights[k] == target:
                        return True
        return False

