class Solution:
    def hasTriple(self, weights: List[int], target: int) -> bool:
        a = sorted(weights)
        for i in range(len(a) - 2):
            j, k = i + 1, len(a) - 1
            while j < k:
                s = a[i] + a[j] + a[k]
                if s == target:
                    return True
                if s < target:
                    j += 1
                else:
                    k -= 1
        return False

