class Solution {
    public boolean hasTriple(int[] weights, int target) {
        int[] a = weights.clone();
        Arrays.sort(a);
        for (int i = 0; i + 2 < a.length; i++) {
            int j = i + 1, k = a.length - 1;
            while (j < k) {
                int s = a[i] + a[j] + a[k];
                if (s == target) return true;
                if (s < target) j++; else k--;
            }
        }
        return false;
    }
}

