static int cmp_int(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

bool hasTriple(int* weights, int weightsSize, int target) {
    int n = weightsSize;
    int* a = malloc(n * sizeof(int));
    memcpy(a, weights, n * sizeof(int));
    qsort(a, n, sizeof(int), cmp_int);
    bool found = false;
    for (int i = 0; i + 2 < n && !found; i++) {
        int j = i + 1, k = n - 1;
        while (j < k) {
            int s = a[i] + a[j] + a[k];
            if (s == target) { found = true; break; }
            if (s < target) j++; else k--;
        }
    }
    free(a);
    return found;
}
